  [["<ARITHMETIC_FUNC_FROM_ABI>", ["0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff", "0x2"], "0x0", "attacker_address"],
   ["<NUMERIC_ARG_FUNC_FROM_ABI>", ["0x0"], "0x0", "attacker_address"],
   ["<NUMERIC_ARG_FUNC_FROM_ABI>", ["0x1"], "0x0", "attacker_address"]]
